parameters.command:
cd /tmp; set -a; . /Users/sbr/gds-agent-benchmarks/.env; set +a; cat > sp.py <<'E'
import os,heapq
from neo4j import GraphDatabase
d=GraphDatabase.driver(os.environ["NEO4J_URI"],auth=(os.environ["NEO4J_USERNAME"],os.environ["NEO4J_PASSWORD"]))
adj={}
with d.session() as s:
    for r in s.run("MATCH (a:UndergroundStation)-[r:LINK]->(b:UndergroundStation) RETURN a.name a,b.name b,r.time t"):
        adj.setdefault(r["a"],[]).append((r["b"],r["t"]))
src="Covent Garden";dist={src:0};prev={};pq=[(0,src)]
while pq:
    c,u=heapq.heappop(pq)
    if c>dist[u]:continue
    for v,t in adj.get(u,[]):
        if c+t<dist.get(v,1e18):dist[v]=c+t;prev[v]=u;heapq.heappush(pq,(c+t,v))
out=[]
for v in dist:
    p=[v]
    while p[-1]!=src:p.append(prev[p[-1]])
    p.reverse()
    cs=[0.0]
    for a,b in zip(p,p[1:]):cs.append(cs[-1]+min(t for x,t in adj[a] if x==b))
    out.append(f"{p}: {cs}")
print(len(out));print(", ".join(out))
E
python3 -I sp.py | head -c 3000

